using Clock=std::chrono::steady_clock;
static bool constant_qp=false;
static void require(bool yes,const char *label){if(!yes)throw std::runtime_error(label);}
static void vk(VkResult r){if(r!=VK_SUCCESS)throw std::runtime_error("Vulkan status "+std::to_string(r));}
