static double us(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::micro>(b-a).count();}
static std::string stats(std::vector<double> v){require(!v.empty(),"Missing samples");std::sort(v.begin(),v.end());char b[160];std::snprintf(b,sizeof(b),"{\"p50\":%.3f,\"p95\":%.3f,\"p99\":%.3f}",v[v.size()/2],v[v.size()*95/100],v[v.size()*99/100]);return b;}
