int main(int argc,char **argv){try{require(argc==3||(argc==4&&std::string(argv[3])=="--cqp28"),"Usage: pyroenc-probe hevc|h264 EXISTING_OUTPUT_DIR [--cqp28]");constant_qp=argc==4;bool h264=std::string(argv[1])=="h264";require(h264||std::string(argv[1])=="hevc","Unsupported codec");require(std::filesystem::is_directory(argv[2]),"Output directory missing");for(int round=0;round<2;++round)for(unsigned step=0;step<2;++step){bool high=round?!step:step;run(high?3840:1920,high?2160:1080,h264,round,argv[2]);}return 0;}catch(const std::exception &e){std::fprintf(stderr,"%s\n",e.what());return 1;}}
